mapper.select:
select count(1) as tsckTotal, sum(t.zzstse + t.xfstse) as tsckTsAmt
  from tl_bjts.ckts_sb_mts_tssb_lsb t
 where t.sbid = #{sbid}
   and t.glh = #{ldlpNo}

select count(1) as mdtsckTotal, sum(t.mdtse) as mdtsckTsAmt
  from TL_BJTS.ckts_sb_mdt_tssb_lsb t
 where t.sbid = #{sbid}
   and t.sbxh = #{ldlpNo}

select count(1) as dbtsTotal,
       sum(tse) as dbtsTsAmt,
       sum(round(t.jsje * t.zssl / 100, 2)) as dbtsSe
  from TL_BJTS.Ckts_Sb_Db_Tssb_Lsb t
 where t.sbid = #{sbid}
   and t.sbxh = #{ldlpNo}
